import java.util.Scanner;
public class JRepeatedSequence2 {
	public static void main(String[] args){
		//Paso 1: Leer el entero N que ingresa el usuario
		Scanner scan = new Scanner(System.in);
		System.out.println("Ingrese el entero N: ");
		int N = scan.nextInt();
		scan.close();
		//Paso 2: Imprimir N numeros separados por espacios
		for (int i = 1; i <= N; i++) {
			//Paso 2.1: Imprimir el numero i-esimo i veces
		    for (int j = 1; j <= i; j++) {
		        System.out.print(i);    
		    } 
		    System.out.print(" ");
		}
	}
}

